window.LPHelpContent={eyebrow:{es:"LearnFlow \xB7 Ayuda",en:"LearnFlow \xB7 Help"},title:{es:"\xBFC\xF3mo funciona LearnFlow?",en:"How does LearnFlow work?"},intro:{es:"LearnFlow es el portal que conecta tres modos de aprendizaje bajo un mismo nivel CEFR compartido (A1\u2013C2). As\xED funciona cada uno:",en:"LearnFlow is the portal that connects three learning apps under one shared CEFR level (A1\u2013C2). Here's how each one works:"},sections:[{id:"deskflow",mark:"L",markClass:"portal",name:"LearnFlow",tag:{es:"Portal",en:"Portal"},summary:{es:"El punto de partida: resume tu progreso combinado y te dice a qu\xE9 app conviene entrar.",en:"The starting point: summarizes your combined progress and tells you which app to open next."},points:[{es:"El anillo de progreso promedia lo completado en las tres apps dentro de tu nivel actual.",en:"The progress ring averages what you've completed across the three apps within your current level."},{es:"Para subir de nivel necesit\xE1s: FluentFlow al {{fluentflow}}%, LyricFlow al {{lyricflow}}% y HubFlow al menos {{hubflow}}% del nivel activo.",en:"To level up you need: FluentFlow at {{fluentflow}}%, LyricFlow at {{lyricflow}}%, and HubFlow at least {{hubflow}}% of the active level."},{es:"La racha cuenta d\xEDas con actividad en cualquiera de las tres apps.",en:"The streak counts days with activity in any of the three apps."}],open:!0},{id:"fluentflow",mark:"F",markClass:"fluent",name:"FluentFlow",tag:{es:"Ruta estructurada",en:"Structured path"},summary:{es:"Ruta secuencial A1\u2013C2, con m\xF3dulos de gram\xE1tica, vocabulario y lectura en orden.",en:"Sequential A1\u2013C2 path, with grammar, vocabulary, and reading modules in order."},points:[{es:"Avanz\xE1s m\xF3dulo a m\xF3dulo dentro de tu nivel; cada uno mezcla teor\xEDa breve y ejercicios.",en:"You move module by module within your level; each one mixes brief theory with exercises."},{es:"El progreso se mide en m\xF3dulos completados sobre el total del nivel.",en:"Progress is measured in modules completed out of the level's total."}]},{id:"hubflow",mark:"H",markClass:"hub",name:"HubFlow",tag:{es:"Pr\xE1ctica tem\xE1tica",en:"Topic practice"},summary:{es:"Pr\xE1ctica libre por tema: ejercicios agrupados en categor\xEDas, con varios modos de juego (incluye Battle 2P).",en:"Free topic practice: exercises grouped in categories, with several game modes (including 2P Battle)."},points:[{es:"Eleg\xEDs categor\xEDa y modo \u2014 no hay un orden obligatorio, es refuerzo flexible.",en:"You pick the category and mode \u2014 there's no required order, it's flexible reinforcement."},{es:"Alcanza con completar el {{hubflow}}% de los ejercicios del nivel para tu parte del avance.",en:"Completing {{hubflow}}% of the level's exercises is enough for your part of the level-up."}]},{id:"lyricflow",mark:"LF",markClass:"lyric",name:"LyricFlow",tag:{es:"Aprendizaje con m\xFAsica",en:"Learning with music"},summary:{es:"Aprend\xE9 escuchando canciones reales, con letras sincronizadas y actividades de comprensi\xF3n.",en:"Learn by listening to real songs, with synced lyrics and comprehension activities."},points:[{es:"Cada canci\xF3n se desbloquea seg\xFAn tu nivel CEFR.",en:"Each song unlocks based on your CEFR level."},{es:"Las actividades (escucha, quiz) refuerzan vocabulario y comprensi\xF3n auditiva.",en:"The activities (listening, quiz) reinforce vocabulary and listening comprehension."}]}]};
